import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.lxr64Vqo.js";const p=JSON.parse('{"title":"Getting Started with NoxMedia","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1795114725000}'),o={name:"guide/getting-started.md"};function n(l,e,d,s,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started-with-noxmedia" tabindex="-1">Getting Started with NoxMedia <a class="header-anchor" href="#getting-started-with-noxmedia" aria-label="Permalink to &quot;Getting Started with NoxMedia&quot;">​</a></h1><p>Welcome to NoxMedia, a self-hosted personal streaming server that converts your Telegram channels and cloud media into a high-performance local media server compatible with Infuse, Vesper, and Nuvio.</p><hr><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>Traditional media servers require large local hard drives and constant file downloads. NoxMedia operates on an on-demand cloud streaming architecture:</p><ul><li><strong>Zero Local Storage Waste</strong>: Stream directly from cloud Telegram storage into your media players without saving gigabytes of video files to disk.</li><li><strong>Universal Client Support</strong>: Connect from Apple TV, iPhone, iPad, and Mac via Infuse and Vesper, or from Android, Windows, and Web via Nuvio.</li><li><strong>Hardware-Decoded DirectPlay</strong>: No server-side transcoding required. Your player hardware handles high-bitrate 4K, HDR, Dolby Vision, and Atmos natively.</li></ul><hr><h2 id="supported-clients-platforms" tabindex="-1">Supported Clients &amp; Platforms <a class="header-anchor" href="#supported-clients-platforms" aria-label="Permalink to &quot;Supported Clients &amp; Platforms&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Client</th><th style="text-align:left;">Supported Operating Systems</th><th style="text-align:left;">Connection Mode</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Infuse</strong></td><td style="text-align:left;">Apple TV (tvOS), iPhone &amp; iPad (iOS), Mac (macOS), Apple Vision Pro (visionOS)</td><td style="text-align:left;">Jellyfin Bridge (Direct Mode)</td></tr><tr><td style="text-align:left;"><strong>Vesper</strong></td><td style="text-align:left;">Mac (macOS), iPhone &amp; iPad (iOS), Apple TV (tvOS)</td><td style="text-align:left;">Jellyfin Bridge</td></tr><tr><td style="text-align:left;"><strong>Nuvio</strong></td><td style="text-align:left;">Android, Windows, macOS, Web</td><td style="text-align:left;">Stremio v3 Addon Protocol</td></tr><tr><td style="text-align:left;"><strong>Kodi / EmbyCon</strong></td><td style="text-align:left;">Android TV, Google TV, Shield TV, Fire TV, PC</td><td style="text-align:left;">Jellyfin Addon / HTTP Stream</td></tr><tr><td style="text-align:left;"><strong>Android TV / Google TV App</strong></td><td style="text-align:left;">Android TV, Google TV</td><td style="text-align:left;">Native App (Coming Soon)</td></tr><tr><td style="text-align:left;"><strong>Windows Desktop</strong></td><td style="text-align:left;">Windows 10, 11</td><td style="text-align:left;">Native Client (Coming Soon)</td></tr><tr><td style="text-align:left;"><strong>Linux Client / Server</strong></td><td style="text-align:left;">Ubuntu, Debian, Arch</td><td style="text-align:left;">Headless Server (Coming Soon)</td></tr></tbody></table><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before setting up NoxMedia, ensure you have:</p><ol><li>An Android device running Android 7.0 or higher (phone, tablet, or TV box) to host the server.</li><li>An active Telegram account.</li><li>Your Telegram API credentials (<code>api_id</code> and <code>api_hash</code>).</li></ol><hr><h2 id="step-1-obtain-telegram-api-credentials" tabindex="-1">Step 1: Obtain Telegram API Credentials <a class="header-anchor" href="#step-1-obtain-telegram-api-credentials" aria-label="Permalink to &quot;Step 1: Obtain Telegram API Credentials&quot;">​</a></h2><p>To stream media through Telegram&#39;s high-speed MTProto network:</p><ol><li>Visit <a href="https://my.telegram.org" target="_blank" rel="noreferrer">my.telegram.org</a> in any web browser.</li><li>Log in using your Telegram phone number (include international country code).</li><li>Click on <strong>API development tools</strong>.</li><li>Fill in the <strong>App title</strong> and <strong>Short name</strong> (for example, <code>NoxMedia</code>).</li><li>Copy your <strong><code>api_id</code></strong> (an integer) and <strong><code>api_hash</code></strong> (a 32-character string).</li></ol><hr><h2 id="step-2-install-and-authenticate-noxmedia" tabindex="-1">Step 2: Install and Authenticate NoxMedia <a class="header-anchor" href="#step-2-install-and-authenticate-noxmedia" aria-label="Permalink to &quot;Step 2: Install and Authenticate NoxMedia&quot;">​</a></h2><ol><li>Download the latest release from the <a href="https://github.com/TheAceOfficials/NoxMedia/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a> page.</li><li>Install the APK on your Android host device.</li><li>Open NoxMedia and enter your <code>api_id</code>, <code>api_hash</code>, and your phone number.</li><li>Enter the verification code sent to your official Telegram app.</li><li>If Two-Step Verification (2FA) is enabled on your account, enter your cloud password when prompted.</li></ol><hr><h2 id="step-3-start-the-server" tabindex="-1">Step 3: Start the Server <a class="header-anchor" href="#step-3-start-the-server" aria-label="Permalink to &quot;Step 3: Start the Server&quot;">​</a></h2><ol><li>From the NoxMedia home screen, toggle the <strong>Server Switch</strong> to ON.</li><li>Grant battery optimization exemptions and notification permissions so Android does not terminate the background service.</li><li>NoxMedia will display your local server address (e.g., <code>http://192.168.1.15:8096</code>).</li></ol><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>Now that your server is active, proceed to connect your streaming clients:</p><ul><li><a href="/NoxMedia/clients/infuse">Connect Apple TV, iOS &amp; Mac via Infuse and Vesper</a></li><li><a href="/NoxMedia/clients/stremio-nuvio">Connect Nuvio Streaming Client</a></li><li><a href="/NoxMedia/clients/android-tv-kodi">Connect Android TV &amp; Kodi</a></li><li><a href="/NoxMedia/roadmap">View Project Roadmap &amp; Progress</a></li></ul>',27)])])}const u=t(o,[["render",n]]);export{p as __pageData,u as default};
